int realtek_ifup(struct netdev_lowerhalf_s *dev)
{
  struct realtek_dev_s *priv = (struct realtek_dev_s *)dev;
  int ret;

  syslog(LOG_INFO, "realtek_ifup: dev=%p devnum=%d mode=%d\n",
         dev, priv->devnum, priv->mode);

  if (IFF_IS_UP(dev->netdev.d_flags))
    {
      syslog(LOG_INFO, "realtek_ifup: interface already UP\n");
      return OK;
    }

  /* If Wi-Fi is not running, start it */
  if (!rltk_wlan_running(priv->devnum))
    {
      syslog(LOG_INFO, "realtek_ifup: starting Wi-Fi for device %d\n", priv->devnum);

      if (priv->devnum == 0 && priv->mode == RTW_MODE_NONE)
        {
          priv->mode = RTW_MODE_STA;
        }

      if (priv->mode != RTW_MODE_NONE)
        {
          ret = wifi_on(priv->mode);
          if (ret < 0)
            {
              syslog(LOG_ERR, "realtek_ifup: wifi_on failed: %d\n", ret);
              return ret;
            }
          syslog(LOG_INFO, "realtek_ifup: wifi_on succeeded\n");
        }
    }

  /* Bring carrier up */
  netdev_lower_carrier_on(dev);
  syslog(LOG_INFO, "realtek_ifup: carrier is ON\n");

  return OK;
}
